761	export function normalizeMarkdown(
762	  input: string,
763	  shouldMergeAdjacentLines = false,
764	): string {
765	  const lines = input.split('\n');
766	  let inCodeBlock = false;
767	  const sanitizedLines: string[] = [];
768	
769	  for (let i = 0; i < lines.length; i++) {
770	    const line = lines[i].trimEnd();
771	    const lastLine = sanitizedLines[sanitizedLines.length - 1];
772	
773	    // Code blocks of ```single line``` don't toggle the inCodeBlock flag
774	    if (CODE_SINGLE_LINE_REGEX.test(line)) {
775	      sanitizedLines.push(line);
776	      continue;
777	    }
778	
779	    // Detect the start or end of a code block
780	    if (CODE_START_REGEX.test(line) || CODE_END_REGEX.test(line)) {
781	      inCodeBlock = !inCodeBlock;
782	      sanitizedLines.push(line);
783	      continue;
784	    }
785	
786	    // If we are inside a code block, keep the line unchanged
787	    if (inCodeBlock) {
788	      sanitizedLines.push(line);
789	      continue;
790	    }
791	
792	    // In markdown the concept of "empty paragraphs" does not exist.
793	    // Blocks must be separated by an empty line. Non-empty adjacent lines must be merged.
794	    if (
795	      line === '' ||
796	      lastLine === '' ||
797	      !lastLine ||
798	      HEADING_REGEX.test(lastLine) ||
799	      HEADING_REGEX.test(line) ||
800	      QUOTE_REGEX.test(line) ||
801	      ORDERED_LIST_REGEX.test(line) ||
802	      UNORDERED_LIST_REGEX.test(line) ||
803	      CHECK_LIST_REGEX.test(line) ||
804	      TABLE_ROW_REG_EXP.test(line) ||
805	      TABLE_ROW_DIVIDER_REG_EXP.test(line) ||
806	      !shouldMergeAdjacentLines ||
807	      TAG_START_REGEX.test(line) ||
808	      TAG_END_REGEX.test(line) ||
809	      ENDS_WITH(TAG_END_REGEX).test(lastLine) ||
810	      ENDS_WITH(TAG_START_REGEX).test(lastLine) ||
811	      CODE_END_REGEX.test(lastLine)
812	    ) {
813	      sanitizedLines.push(line);
814	    } else {
815	      sanitizedLines[sanitizedLines.length - 1] =
816	        lastLine + ' ' + line.trimStart();
817	    }
818	  }
819	
820	  return sanitizedLines.join('\n');
821	}
